def build_market_news_context(host_root, mode):
    feed = load_market_news_phase1_feed()
    block = feed["pre_market"] if mode == "pre_market" else feed["post_market"]
    route_path = "/market/pre-market-news" if mode == "pre_market" else "/market/post-market-wrap"
    title_label = "Pre-Market News" if mode == "pre_market" else "Post-Market Wrap"
    today_iso = get_today_ist().isoformat()
    return {
        "seo_title": f"{title_label} | TraderHub Market News",
        "seo_description": f"Read {title_label.lower()} with curated lead stories, watch sections, and market-moving context in TraderHub.",
        "canonical_url": f"{host_root.rstrip('/')}{route_path}",
        "schema_json": json.dumps({"@context": "https://schema.org", "@type": "WebPage", "name": f"{title_label} | TraderHub", "description": f"Public market news page for {title_label.lower()}.", "url": f"{host_root.rstrip('/')}{route_path}"}, indent=2),
        "breadcrumb_text": f"Market News › {title_label}",
        "breadcrumb_meta_text": f"Phase 1 public market news | Last reviewed {today_iso}",
        "hero_kicker": "TraderHub Market News",
        "hero_title": block["hero_title"],
        "hero_subtitle": block["hero_subtitle"],
        "hero_metric_primary": block["hero_metric_primary"],
        "hero_metric_secondary": block["hero_metric_secondary"],
        "hero_badges": [{"label": "Phase 1 Public Module", "kind": "tag-info"}, {"label": "SEO Ready", "kind": "tag-up"}, {"label": title_label, "kind": "tag-warn"}],
        "hero_stats": [
            {"label": "Lead Stories", "value": len(block["lead_stories"])},
            {"label": "Watch Blocks", "value": len(block["watch_sections"])},
            {"label": "Theme", "value": "Current Site"},
            {"label": "Mode", "value": title_label},
        ],
        "nav_chips": [
            {"label": "Pre-Market", "href": "/market/pre-market-news"},
            {"label": "Post-Market", "href": "/market/post-market-wrap"},
        ],
        "section_title": title_label,
        "section_note": "This page is built for repeat traffic and market habit. It should help a user get oriented quickly without making them work through a noisy stream of generic headlines.",
        "summary_cards": block["summary_cards"],
        "lead_stories": block["lead_stories"],
        "watch_sections": block["watch_sections"],
        "side_box_title": block["side_box_title"],
        "side_box_copy": block["side_box_copy"],
        "why_page_works": block["why_page_works"],
    }


def get_phase2_market_symbols(limit=18):
    symbols = []
    seen = set()

    def add_symbol(symbol):
        if symbol and symbol not in seen:
            seen.add(symbol)
            symbols.append(symbol)

    for symbol in NIFTY_50_SYMBOLS:
        add_symbol(symbol)
    for symbol in get_liquid_equity_symbols():
        add_symbol(symbol)
    return symbols[:limit]


def get_broad_sector_label(symbol):
    sector_label = get_symbol_sector_lookup().get(symbol, "General")
    return sector_label.split(" / ")[0] if " / " in sector_label else sector_label


def get_public_sector_route_for_label(sector_label):
    cleaned = str(sector_label or "").strip().lower()
    direct_map = {
        "fmcg": "/sectors/fmcg",
        "it": "/sectors/it",
        "technology": "/sectors/it",
        "auto": "/sectors/auto",
        "auto & mobility": "/sectors/auto",
        "oil gas": "/sectors/oil-gas",
        "oil & gas": "/sectors/oil-gas",
        "oil and gas": "/sectors/oil-gas",
        "private banks": "/sectors/private-banks",
        "psu banks": "/sectors/psu-banks",
        "financials": "/sectors/private-banks",
        "healthcare": "/market/sector-news",
        "industrials": "/market/sector-news",
        "general": "/market/sector-news",
    }
    return direct_map.get(cleaned, "/market/sector-news")


def get_public_sector_cta_label(sector_label):
    href = get_public_sector_route_for_label(sector_label)
    return "Open Sector Page" if href.startswith("/sectors/") else "Open Sector News"


def build_live_mover_story(row, sector_label):
    if not row:
        return "This stock is waiting for a stronger live market snapshot."
    direction = "higher" if row["change_pct_numeric"] > 0 else "lower" if row["change_pct_numeric"] < 0 else "flat"
    move_text = row["change_pct_display"]
    gap_text = row["gap_text"]
    status_label = row["status_label"]
    vwap_status = row["vwap_status"]
    return (
        f"{row['symbol']} is trading {direction} by {move_text} inside the {sector_label} space. "
        f"It opened with a {gap_text} gap, is currently {vwap_status.lower()}, and the tape is reading as {status_label.lower()}."
    )


def build_reason_tags(row, sector_label=None):
    if not row:
        return []
    tags = []
    if row["gap_pct_numeric"] > 0:
        tags.append({"label": f"Gap Up {row['gap_text']}", "kind": "tag-up"})
    elif row["gap_pct_numeric"] < 0:
        tags.append({"label": f"Gap Down {row['gap_text']}", "kind": "tag-down"})

    if row["vwap_status"] == "Above VWAP":
        tags.append({"label": "Above VWAP", "kind": "tag-up"})
    elif row["vwap_status"] == "Below VWAP":
        tags.append({"label": "Below VWAP", "kind": "tag-down"})
    else:
        tags.append({"label": row["vwap_status"], "kind": "tag-info"})

    if row["status_label"] == "Above PDH":
        tags.append({"label": "Above PDH", "kind": "tag-up"})
    elif row["status_label"] == "Below PDL":
        tags.append({"label": "Below PDL", "kind": "tag-down"})
    else:
        tags.append({"label": row["status_label"], "kind": "tag-warn"})

    if row["day_range_percent"] >= 75:
        tags.append({"label": "Near Day High", "kind": "tag-up"})
    elif row["day_range_percent"] <= 25:
        tags.append({"label": "Near Day Low", "kind": "tag-down"})

    if sector_label:
        tags.append({"label": sector_label, "kind": "tag-info"})
    return tags[:5]


def build_sector_strip_story(sector_label, rows):
    if not rows:
        return f"{sector_label} is staged for the news stream, but live rows are unavailable right now."
    avg_change = sum(row["change_pct_numeric"] for row in rows) / len(rows)
    strongest = max(rows, key=lambda item: item["change_pct_numeric"])
    weakest = min(rows, key=lambda item: item["change_pct_numeric"])
    if avg_change > 0.35:
        tone = "constructive"
    elif avg_change < -0.35:
        tone = "defensive"
    else:
        tone = "mixed"
    return (
        f"{sector_label} is trading with a {tone} tone right now. "
        f"{strongest['symbol']} is leading at {strongest['change_pct_display']}, while {weakest['symbol']} is lagging at {weakest['change_pct_display']}."
    )


def build_why_moving_reason_cards(row):
    if not row:
        return [
            {"label": "Move", "value": "Pending", "copy": "Live price context is unavailable right now."},
            {"label": "Gap", "value": "Pending", "copy": "Opening context will appear when a valid quote snapshot is available."},
            {"label": "VWAP", "value": "Pending", "copy": "Intraday average-price positioning is reserved for the live market path."},
            {"label": "Status", "value": "Pending", "copy": "Breakout or rejection context will appear with live row data."},
        ]
    return [
        {"label": "Move", "value": row["change_pct_display"], "copy": f"Current move versus previous close with last price at {row['last_price']}."},
        {"label": "Gap", "value": row["gap_text"], "copy": f"Opening gap context versus the previous close. Open was {row['open_price']}."},
        {"label": "VWAP", "value": row["vwap_status"], "copy": f"Average-price position is using VWAP {row['vwap']} as the intraday anchor."},
        {"label": "Status", "value": row["status_label"], "copy": f"Public status read based on PDH/PDL and intraday location. Current day range fill is {row['day_range_percent']}%."},
    ]


