def fetch_internal_seo_page_snapshot(page_row):
    with app.test_client() as client:
        response = client.get(
            page_row["path"],
            base_url=f"https://{page_row['domain']}",
            follow_redirects=True,
        )
    html_text = response.get_data(as_text=True)
    snapshot = extract_seo_snapshot_from_html(
        html_text,
        fallback_url=page_row["url"],
    )
    snapshot["status_code"] = response.status_code
    snapshot["last_checked_at"] = utcnow_iso()
    return snapshot


def fetch_internal_seo_page_render(page_row):
    with app.test_client() as client:
        response = client.get(
            page_row["path"],
            base_url=f"https://{page_row['domain']}",
            follow_redirects=True,
        )
    return {
        "status_code": response.status_code,
        "html_text": response.get_data(as_text=True),
        "final_path": response.request.path if getattr(response, "request", None) else page_row["path"],
        "final_url": page_row["url"],
    }


def extract_news_page_snapshot_from_html(page_row, html_text):
    href_matches = re.findall(r'<a[^>]+href=["\'](.*?)["\']', html_text or "", flags=re.IGNORECASE)
    internal_hrefs = [
        href
        for href in href_matches
        if href.startswith("/")
        or href.startswith(f"https://{page_row['domain']}/")
        or href.startswith("https://traderhub.in/")
    ]
    stock_links = {
        href
        for href in internal_hrefs
        if "/stocks/" in href
    }
    story_links = {
        href
        for href in internal_hrefs
        if any(
            token in href
            for token in (
                "/stocks/",
                "/market/archive/",
                "/market/trends/",
                "/sectors/",
            )
        )
    }
    section_count = len(re.findall(r"<section\b", html_text or "", flags=re.IGNORECASE))
    article_count = len(re.findall(r"<article\b", html_text or "", flags=re.IGNORECASE))
    heading_count = len(re.findall(r"<h2\b", html_text or "", flags=re.IGNORECASE))
    bullet_count = len(re.findall(r"<li\b", html_text or "", flags=re.IGNORECASE))
    text_content = _clean_extracted_html_text(html_text or "").lower()
    summary_present = bool(
        re.search(
            r"\b(editor summary|market summary|sector summary|stock summary|trend summary|archive summary|key takeaways|what matters)\b",
            text_content,
            flags=re.IGNORECASE,
        )
    )
    fallback_active = bool(
        re.search(
            r"\b(source pending|waiting for a stronger|structured archive shell|placeholder|pending\b|fallback)\b",
            text_content,
            flags=re.IGNORECASE,
        )
    )
    market_error_present = bool(
        re.search(
            r"\b(market error|could not build a reliable market snapshot|unable to complete|source unavailable)\b",
            text_content,
            flags=re.IGNORECASE,
        )
    )
    shell_only = bool(
        len(story_links) == 0
        and len(stock_links) == 0
        and (section_count + article_count + heading_count) <= 3
        and bullet_count <= 2
    )
    notes = []
    if fallback_active:
        notes.append("fallback-copy")
    if market_error_present:
        notes.append("market-error")
    if shell_only:
        notes.append("shell-only")
    return {
        "story_link_count": len(story_links),
        "stock_link_count": len(stock_links),
        "section_count": section_count + article_count + heading_count,
        "bullet_count": bullet_count,
        "summary_present": summary_present,
        "fallback_active": fallback_active,
        "market_error_present": market_error_present,
        "shell_only": shell_only,
        "checked_at": utcnow_iso(),
        "notes": ", ".join(notes),
    }


def extract_internal_links_from_html(html_text, fallback_url=""):
    if not html_text:
        return []
    href_matches = re.findall(r'<a[^>]+href=["\'](.*?)["\']', html_text, flags=re.IGNORECASE)
    allowed_domains = {"traderhub.in", "app.traderhub.in", "bot.traderhub.in"}
    links = []
    seen = set()
    for href in href_matches:
        raw_href = str(href or "").strip()
        if (
            not raw_href
            or raw_href.startswith("#")
            or raw_href.lower().startswith(("javascript:", "mailto:", "tel:"))
        ):
            continue
        absolute_url = urllib.parse.urljoin(fallback_url, raw_href)
        parsed = urllib.parse.urlparse(absolute_url)
        if parsed.scheme not in ("http", "https") or parsed.netloc.lower() not in allowed_domains:
            continue
        normalized_url = urllib.parse.urlunparse(
            (
                parsed.scheme,
                parsed.netloc.lower(),
                parsed.path or "/",
                "",
                parsed.query,
                "",
            )
        )
        if normalized_url in seen:
            continue
        seen.add(normalized_url)
        links.append({"to_url": normalized_url, "link_type": "internal"})
    return links


def run_seo_metadata_extract(limit=100, domain=None, only_missing=False, profile="safe"):
    check_id = start_check(
        "metadata_extract",
        notes=f"Metadata extraction run | domain={domain or 'all'} | limit={limit} | profile={profile}",
    )
    pages_scanned = 0
    failures = 0
    try:
        profile_map = get_seo_extractor_profiles()
        selected_page_types = profile_map.get(profile, profile_map["safe"])
        page_rows = fetch_seo_pages_for_extraction(
            domain=domain,
            limit=limit,
            only_missing=only_missing,
            page_types=selected_page_types or None,
        )
        for page_row in page_rows:
            try:
                snapshot = fetch_internal_seo_page_snapshot(page_row)
            except BaseException as exc:
                failures += 1
                snapshot = {
                    "title": "",
                    "meta_description": "",
                    "h1": "",
                    "canonical_url": page_row["url"],
                    "robots_directive": page_row.get("robots_directive") or "",
                    "index_status": page_row.get("index_status") or page_row.get("index_expected") or "noindex",
                    "status_code": 500,
                    "schema_type": page_row.get("schema_type") or "WebPage",
                    "last_checked_at": utcnow_iso(),
                }
            update_seo_page_snapshot(page_row["id"], snapshot)
            pages_scanned += 1
        finish_check(
            check_id,
            "completed",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes=f"Completed metadata extraction for {pages_scanned} pages with {failures} failures.",
        )
        summary = get_extraction_summary()
        summary["pages_scanned"] = pages_scanned
        summary["failures"] = failures
        summary["domain"] = domain or "all"
        summary["only_missing"] = bool(only_missing)
        summary["profile"] = profile
        summary["page_types"] = selected_page_types
        return summary
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes=f"Metadata extraction failed: {exc}",
        )
        raise


def run_seo_metadata_debug(url):
    diagnostics = {"status": "ok", "url": url}
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme in {"http", "https"} and parsed.path:
            page_row = {
                "url": url,
                "path": parsed.path,
                "domain": parsed.netloc,
            }
            snapshot = fetch_internal_seo_page_snapshot(page_row)
        else:
            snapshot = fetch_seo_page_snapshot(url)
        diagnostics["snapshot"] = snapshot
        return diagnostics
    except BaseException as exc:
        diagnostics["status"] = "error"
        diagnostics["message"] = str(exc)
        diagnostics["error_type"] = type(exc).__name__
        return diagnostics


def build_seo_issue_records(page_row):
    issues = []
    detected_at = utcnow_iso()
    page_label = page_row.get("url") or page_row.get("path") or "page"
    title = str(page_row.get("title") or "").strip()
    meta_description = str(page_row.get("meta_description") or "").strip()
    h1 = str(page_row.get("h1") or "").strip()
    canonical_url = str(page_row.get("canonical_url") or "").strip()
    robots_directive = str(page_row.get("robots_directive") or "").strip()
    index_status = str(page_row.get("index_status") or "").strip().lower()
    index_expected = str(page_row.get("index_expected") or "").strip().lower()
    schema_type = str(page_row.get("schema_type") or "").strip()
    status_code = page_row.get("status_code")
    expected_canonical_domain = "traderhub.in" if page_row.get("domain") == "traderhub.in" else None

    if not title:
        issues.append(
            {
                "issue_type": "missing_title",
                "severity": "high",
                "message": f"{page_label} is missing a <title> tag.",
                "detected_at": detected_at,
            }
        )
    if not meta_description:
        issues.append(
            {
                "issue_type": "missing_meta_description",
                "severity": "medium",
                "message": f"{page_label} is missing a meta description.",
                "detected_at": detected_at,
            }
        )
    if not robots_directive:
        issues.append(
            {
                "issue_type": "missing_robots_directive",
                "severity": "low",
                "message": f"{page_label} is missing a robots directive.",
                "detected_at": detected_at,
            }
        )
    if not h1:
        issues.append(
            {
                "issue_type": "missing_h1",
                "severity": "medium",
                "message": f"{page_label} is missing an H1 heading.",
                "detected_at": detected_at,
            }
        )
    if not canonical_url:
        issues.append(
            {
                "issue_type": "missing_canonical",
                "severity": "medium",
                "message": f"{page_label} is missing a canonical URL.",
                "detected_at": detected_at,
            }
        )
    elif expected_canonical_domain and expected_canonical_domain not in canonical_url:
        issues.append(
            {
                "issue_type": "canonical_mismatch",
                "severity": "high",
                "message": f"{page_label} should canonicalize to {expected_canonical_domain}, but currently points to {canonical_url}.",
                "detected_at": detected_at,
            }
        )
    if not schema_type:
        issues.append(
            {
                "issue_type": "missing_schema",
                "severity": "low",
                "message": f"{page_label} is missing structured data markup.",
                "detected_at": detected_at,
            }
        )
    if page_row.get("domain") == "traderhub.in" and status_code not in (200, None):
        issues.append(
            {
                "issue_type": "non_200_public_page",
                "severity": "high",
                "message": f"{page_label} returned HTTP {status_code}.",
                "detected_at": detected_at,
            }
        )
    if page_row.get("domain") == "traderhub.in" and index_expected == "index" and index_status and index_status != "index":
        issues.append(
            {
                "issue_type": "expected_public_not_indexable",
                "severity": "high",
                "message": f"{page_label} is expected to be indexable but currently resolves to {index_status}.",
                "detected_at": detected_at,
            }
        )
    if page_row.get("domain") != "traderhub.in" and index_expected == "noindex" and index_status == "index":
        issues.append(
            {
                "issue_type": "unexpected_indexable",
                "severity": "high",
                "message": f"{page_label} is expected to stay noindex on {page_row.get('domain')} but currently resolves as indexable.",
                "detected_at": detected_at,
            }
        )
    return issues


def run_seo_issue_detection(limit=100, domain=None, only_checked=True, profile="public-core"):
    profile_map = get_seo_extractor_profiles()
    selected_page_types = profile_map.get(profile, profile_map["public-core"])
    check_id = start_check(
        "issue_detect",
        notes=f"Issue detection run | domain={domain or 'all'} | limit={limit} | profile={profile}",
    )
    try:
        page_rows = fetch_seo_pages_for_issue_detection(
            domain=domain,
            limit=limit,
            only_checked=only_checked,
            page_types=selected_page_types or None,
        )
        issue_map = {}
        issue_total = 0
        pages_with_issues = 0
        page_ids = []
        for page_row in page_rows:
            issues = build_seo_issue_records(page_row)
            issue_map[page_row["id"]] = issues
            page_ids.append(page_row["id"])
            if issues:
                pages_with_issues += 1
                issue_total += len(issues)

        replace_page_issues(issue_map)
        recompute_health_scores(page_ids=page_ids)
        finish_check(
            check_id,
            "completed",
            pages_scanned=len(page_rows),
            issues_found=issue_total,
            notes=f"Issue detection completed for {len(page_rows)} pages with {issue_total} active issues.",
        )
        summary = get_issue_summary()
        summary["pages_scanned"] = len(page_rows)
        summary["pages_with_issues"] = pages_with_issues
        summary["domain"] = domain or "all"
        summary["profile"] = profile
        summary["page_types"] = selected_page_types
        return summary
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=0,
            issues_found=0,
            notes=f"Issue detection failed: {exc}",
        )
        raise


def run_seo_issue_debug(url):
    diagnostics = {"status": "ok", "url": url}
    try:
        parsed = urllib.parse.urlparse(url)
        path = parsed.path or "/"
        page_row = {
            "url": url,
            "path": path,
            "domain": parsed.netloc or "traderhub.in",
        }
        snapshot = fetch_internal_seo_page_snapshot(page_row)
        page_row.update(snapshot)
        diagnostics["issues"] = build_seo_issue_records(page_row)
        diagnostics["snapshot"] = snapshot
        return diagnostics
    except BaseException as exc:
        diagnostics["status"] = "error"
        diagnostics["message"] = str(exc)
        diagnostics["error_type"] = type(exc).__name__
        return diagnostics


def refresh_seo_snapshot_for_url(url):
    page_row = fetch_seo_page_by_url(url)
    if not page_row:
        raise ValueError(f"SEO page record not found for {url}")
    snapshot = fetch_internal_seo_page_snapshot(page_row)
    update_seo_page_snapshot(page_row["id"], snapshot)
    refreshed_row = fetch_seo_page_by_url(url) or {}
    return {"page": refreshed_row, "snapshot": snapshot}


def refresh_seo_snapshots_for_issue_type(issue_type=None, limit=25):
    page_rows = fetch_active_issue_pages(issue_type=issue_type, limit=limit)
    refreshed = []
    failures = []
    for page_row in page_rows:
        try:
            payload = refresh_seo_snapshot_for_url(page_row["url"])
            refreshed.append(payload["page"]["url"])
        except BaseException as exc:
            failures.append({"url": page_row["url"], "message": str(exc), "error_type": type(exc).__name__})
    return {
        "issue_type": issue_type or "all",
        "requested_limit": limit,
        "refreshed_count": len(refreshed),
        "refreshed_urls": refreshed,
        "failures": failures,
    }


def get_news_snapshot_profiles():
    return {
        "summary-core": ["trend", "archive", "sector_archive"],
        "summary-wide": ["trend", "archive", "sector_archive", "stock_archive", "stock_news"],
        "summary-live": ["market_news", "alerts_prep"],
        "summary-full": [],
    }


def run_news_snapshot_scan(limit=40, domain=None, profile="summary-core", offset=0, only_missing=True):
    profile_map = get_news_snapshot_profiles()
    requested_limit = int(limit)
    close_stale_running_checks("news_snapshot_scan", older_than_minutes=3, status="timed_out")
    if profile == "summary-live":
        effective_limit = min(requested_limit, 6)
    elif profile == "summary-full":
        effective_limit = min(requested_limit, 8)
    else:
        effective_limit = min(requested_limit, 10)
    selected_page_types = profile_map.get(profile, profile_map["summary-core"])
    check_id = start_check(
        "news_snapshot_scan",
        notes=(
            f"News snapshot scan | domain={domain or 'all'} | "
            f"limit={requested_limit} | effective_limit={effective_limit} | "
            f"offset={offset} | profile={profile} | only_missing={int(bool(only_missing))}"
        ),
    )
    try:
        page_rows = fetch_news_pages_for_snapshot_scan(
            domain=domain,
            limit=effective_limit,
            offset=offset,
            page_types=selected_page_types or None,
            only_missing=only_missing,
        )
        failures = []
        for page_row in page_rows:
            try:
                render_payload = fetch_internal_seo_page_render(page_row)
                snapshot = extract_news_page_snapshot_from_html(page_row, render_payload.get("html_text", ""))
                upsert_news_page_snapshot(page_row, snapshot)
            except BaseException as exc:
                failures.append({"url": page_row["url"], "message": str(exc), "error_type": type(exc).__name__})
        finish_check(
            check_id,
            "completed",
            pages_scanned=len(page_rows),
            issues_found=len(failures),
            notes=f"News snapshot scan completed for {len(page_rows)} pages with {len(failures)} failures.",
        )
        summary = get_news_snapshot_run_summary()
        summary.update(
            {
                "status": "ok",
                "domain": domain or "all",
                "profile": profile,
                "requested_limit": requested_limit,
                "effective_limit": effective_limit,
                "offset": int(offset),
                "only_missing": bool(only_missing),
                "pages_scanned": len(page_rows),
                "failures": failures,
            }
        )
        return summary
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=0,
            issues_found=0,
            notes=f"News snapshot scan failed: {exc}",
        )
        raise


def run_seo_crawlability_scan(limit=100, domain=None, profile="graph-core", offset=0, only_unlinked=True):
    requested_limit = int(limit)
    effective_limit = requested_limit
    if profile == "full":
        effective_limit = min(requested_limit, 30)
    elif profile == "graph-wide":
        effective_limit = min(requested_limit, 35)
    elif profile == "graph-core":
        effective_limit = min(requested_limit, 40)
    elif profile == "public-plus":
        effective_limit = min(requested_limit, 40)
    else:
        effective_limit = min(requested_limit, 60)
    check_id = start_check(
        "crawlability_scan",
        notes=f"Crawlability link scan | domain={domain or 'all'} | limit={effective_limit} | offset={offset} | profile={profile} | only_unlinked={int(bool(only_unlinked))}",
    )
    pages_scanned = 0
    failures = 0
    total_links = 0
    failure_messages = []
    try:
        profile_map = get_seo_extractor_profiles()
        selected_page_types = profile_map.get(profile, profile_map["public-plus"])
        remaining_before = count_seo_pages_for_link_scan(
            domain=domain,
            page_types=selected_page_types or None,
            only_checked=True,
            only_unlinked=only_unlinked,
        )
        page_rows = fetch_seo_pages_for_link_scan(
            domain=domain,
            limit=effective_limit,
            offset=offset,
            only_checked=True,
            page_types=selected_page_types or None,
            only_unlinked=only_unlinked,
        )
        for page_row in page_rows:
            try:
                render_data = fetch_internal_seo_page_render(page_row)
                links = extract_internal_links_from_html(
                    render_data["html_text"],
                    fallback_url=page_row["url"],
                )
                replace_page_crawl_links(page_row["id"], page_row["url"], links)
                pages_scanned += 1
                total_links += len(links)
            except BaseException as exc:
                failures += 1
                failure_messages.append(f"{page_row['url']}: {type(exc).__name__}: {exc}")
        finish_check(
            check_id,
            "completed" if failures == 0 else "completed_with_warnings",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes="; ".join(failure_messages[:5]),
        )
        return {
            "status": "ok",
            "domain": domain or "all",
            "profile": profile,
            "requested_limit": requested_limit,
            "effective_limit": effective_limit,
            "offset": offset,
            "only_unlinked": bool(only_unlinked),
            "remaining_before": remaining_before,
            "remaining_after": max(0, remaining_before - pages_scanned),
            "pages_scanned": pages_scanned,
            "total_links": total_links,
            "failures": failures,
            "summary": get_crawlability_overview(limit=100),
        }
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=pages_scanned,
            issues_found=failures,
            notes=f"{type(exc).__name__}: {exc}",
        )
        raise


def _format_sitemap_lastmod(value):
    if not value:
        return get_today_ist().isoformat()
    try:
        return datetime.datetime.fromisoformat(str(value)).date().isoformat()
    except Exception:
        return get_today_ist().isoformat()


def _build_sitemap_xml(url_rows):
    lines = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
    for row in url_rows:
        lines.append("  <url>")
        lines.append(f"    <loc>{html_lib.escape(row['url'])}</loc>")
        lines.append(f"    <lastmod>{_format_sitemap_lastmod(row.get('last_checked_at'))}</lastmod>")
        lines.append("  </url>")
    lines.append("</urlset>")
    return "\n".join(lines)


def _build_sitemap_index_xml(sitemap_entries):
    lines = ['<?xml version="1.0" encoding="UTF-8"?>', '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">']
    for entry in sitemap_entries:
        lines.append("  <sitemap>")
        lines.append(f"    <loc>{html_lib.escape(entry['public_url'])}</loc>")
        lines.append(f"    <lastmod>{_format_sitemap_lastmod(entry.get('last_generated_at'))}</lastmod>")
        lines.append("  </sitemap>")
    lines.append("</sitemapindex>")
    return "\n".join(lines)


def run_seo_sitemap_generation():
    check_id = start_check("sitemap_build", notes="Generate sitemap XML from eligible public SEO pages")
    try:
        eligible_pages = fetch_sitemap_eligible_pages()
        grouped = {}
        for row in eligible_pages:
            grouped.setdefault(row["sitemap_group"], []).append(row)

        SITEMAP_DIR.mkdir(parents=True, exist_ok=True)
        generated_at = utcnow_iso()
        sitemap_rows = []
        for sitemap_group, rows in sorted(grouped.items()):
            sitemap_name = f"{sitemap_group}.xml"
            file_path = SITEMAP_DIR / sitemap_name
            public_url = f"https://traderhub.in/sitemaps/{sitemap_name}"
            file_path.write_text(_build_sitemap_xml(rows), encoding="utf-8")
            sitemap_rows.append(
                {
                    "sitemap_name": sitemap_name,
                    "domain": "traderhub.in",
                    "sitemap_type": sitemap_group,
                    "file_path": str(file_path),
                    "public_url": public_url,
                    "url_count": len(rows),
                    "last_generated_at": generated_at,
                    "status": "completed",
                    "notes": f"Generated from {len(rows)} eligible public URLs.",
                }
            )

        index_path = SITEMAP_DIR / "sitemap.xml"
        index_public_url = "https://traderhub.in/sitemap.xml"
        index_path.write_text(_build_sitemap_index_xml(sitemap_rows), encoding="utf-8")
        sitemap_rows.insert(
            0,
            {
                "sitemap_name": "sitemap.xml",
                "domain": "traderhub.in",
                "sitemap_type": "index",
                "file_path": str(index_path),
                "public_url": index_public_url,
                "url_count": len(sitemap_rows),
                "last_generated_at": generated_at,
                "status": "completed",
                "notes": "Top-level sitemap index for TraderHub public SEO pages.",
            },
        )

        replace_sitemap_records(sitemap_rows)
        finish_check(
            check_id,
            "completed",
            pages_scanned=len(eligible_pages),
            issues_found=0,
            notes=f"Generated {len(sitemap_rows)} sitemap files from {len(eligible_pages)} pages.",
        )
        return {
            "generated_files": len(sitemap_rows),
            "eligible_pages": len(eligible_pages),
            "groups": {group: len(rows) for group, rows in sorted(grouped.items())},
            "records": sitemap_rows,
        }
    except BaseException as exc:
        finish_check(
            check_id,
            "failed",
            pages_scanned=0,
            issues_found=0,
            notes=f"Sitemap generation failed: {exc}",
        )
        raise


SEO_MANAGER_TEMPLATE = """
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{ page_title }}</title>
  <meta name="description" content="{{ page_description }}">
  <style>
    :root { --bg:#eef2f6; --paper:#fff; --panel:#f7fafc; --line:#d4dbe3; --ink:#1f2b38; --muted:#627385; --up:#166b45; --up-soft:#daf0e4; --warn:#9a6c00; --warn-soft:#f6ebc5; --danger:#9a3337; --danger-soft:#f7dddf; --info:#245fa7; --info-soft:#dbe8fb; --shadow:0 10px 28px rgba(23,33,43,0.08); }
    * { box-sizing:border-box; } body { margin:0; font-family:Arial,Helvetica,sans-serif; color:var(--ink); background:linear-gradient(180deg,#f7f7f5 0%,#eef2f6 100%); }
    .page { max-width:1440px; margin:0 auto; padding:18px 14px 34px; }
    .microbar { display:flex; justify-content:space-between; gap:12px; flex-wrap:wrap; color:var(--muted); font-size:13px; margin-bottom:14px; }
    .hero,.panel,.card,.table-wrap,.sidebar { background:var(--paper); border:1px solid var(--line); border-radius:20px; box-shadow:var(--shadow); }
    .hero { padding:20px 22px; background:linear-gradient(145deg,#21465c,#2b7d72 72%,#4e9a8a 100%); color:#fff; }
    .hero h1 { margin:0; font-size:34px; line-height:1; } .hero-sub { margin-top:8px; color:rgba(255,255,255,0.84); font-size:16px; }
    .nav { display:flex; gap:10px; overflow-x:auto; padding:14px 0 4px; }
    .chip { text-decoration:none; border:1px solid var(--line); background:var(--paper); color:#0e554b; border-radius:999px; padding:10px 14px; font-size:13px; font-weight:700; white-space:nowrap; }
    .chip.active { background:#0e554b; color:#fff; border-color:#0e554b; }
    .kpi-grid { display:grid; grid-template-columns:repeat(6,minmax(0,1fr)); gap:12px; margin-top:16px; }
    .card { padding:14px; background:var(--panel); min-width:0; overflow:hidden; }
    .label { font-size:11px; text-transform:uppercase; letter-spacing:.08em; color:var(--muted); font-weight:700; margin-bottom:6px; white-space:normal; overflow-wrap:anywhere; }
    .value { font-size:28px; font-weight:700; color:var(--ink); min-width:0; line-height:1.08; white-space:normal; overflow-wrap:anywhere; word-break:break-word; }
    .layout { display:grid; grid-template-columns:minmax(0,1fr) 320px; gap:16px; margin-top:16px; align-items:start; }
    .stack { display:grid; gap:16px; } .panel { padding:16px; } .panel h2 { margin:0 0 6px; font-size:24px; } .note { color:var(--muted); font-size:14px; line-height:1.55; margin-bottom:12px; }
    .grid-2 { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:16px; }
    table { width:100%; border-collapse:collapse; font-size:14px; } th { text-align:left; font-size:11px; text-transform:uppercase; letter-spacing:.08em; color:var(--muted); border-bottom:1px solid var(--line); padding:9px 8px; white-space:nowrap; } td { padding:10px 8px; border-bottom:1px solid rgba(212,219,227,.88); vertical-align:top; } tr:last-child td { border-bottom:none; }
    .tag { display:inline-flex; align-items:center; padding:6px 10px; border-radius:999px; font-size:12px; font-weight:700; }
    .tag-high { background:var(--danger-soft); color:var(--danger); } .tag-medium { background:var(--warn-soft); color:var(--warn); } .tag-low { background:var(--info-soft); color:var(--info); } .tag-good { background:var(--up-soft); color:var(--up); }
    .mono { font-family:Consolas,Menlo,monospace; font-size:12px; word-break:break-all; } .muted { color:var(--muted); }
    .sidebar { padding:16px; } .sidebar h3 { margin:0 0 10px; font-size:15px; text-transform:uppercase; letter-spacing:.08em; color:var(--muted); }
    .mini-list { display:grid; gap:10px; } .mini-row { padding-bottom:10px; border-bottom:1px solid rgba(212,219,227,.88); } .mini-row:last-child { padding-bottom:0; border-bottom:none; }
    .filters { display:flex; gap:10px; flex-wrap:wrap; margin-bottom:12px; } .filter-chip { padding:8px 12px; border-radius:999px; border:1px solid var(--line); background:var(--panel); font-size:12px; }
    @media (max-width:1160px) { .layout { grid-template-columns:1fr; } .grid-2,.kpi-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } }
    @media (max-width:680px) { .kpi-grid,.grid-2 { grid-template-columns:1fr; } .hero h1 { font-size:28px; } .page { padding:12px 10px 28px; } .card { padding:12px; } .value { font-size:22px; } }
  </style>
</head>
<body>
  <div class="page">
    <div class="microbar"><div>{{ breadcrumb_text }}</div><div>{{ breadcrumb_meta_text }}</div></div>
    <section class="hero">
      <h1>{{ hero_title }}</h1>
      <div class="hero-sub">{{ hero_subtitle }}</div>
      <div class="kpi-grid">
        {% for item in kpis %}
        <div class="card">
          <div class="label">{{ item.label }}</div>
          <div class="value">{{ item.value }}</div>
        </div>
        {% endfor %}
      </div>
    </section>
    <div class="nav">
      {% for nav in nav_items %}
      <a class="chip {% if nav.href == active_href %}active{% endif %}" href="{{ nav.href }}">{{ nav.label }}</a>
      {% endfor %}
    </div>
    <div class="layout">
      <div class="stack">
        {% for section in sections %}
        <section class="panel">
          <h2>{{ section.title }}</h2>
          {% if section.note %}<div class="note">{{ section.note }}</div>{% endif %}
          {% if section.filters %}
          <div class="filters">{% for chip in section.filters %}<span class="filter-chip">{{ chip }}</span>{% endfor %}</div>
          {% endif %}
          {% if section.rows %}
          <div class="table-wrap">
            <table>
              <thead><tr>{% for col in section.columns %}<th>{{ col }}</th>{% endfor %}</tr></thead>
              <tbody>
                {% for row in section.rows %}
                <tr>
                  {% for cell in row %}
                  <td>{{ cell|safe }}</td>
                  {% endfor %}
                </tr>
                {% endfor %}
              </tbody>
            </table>
          </div>
          {% else %}
          <div class="note">No rows to show right now.</div>
          {% endif %}
        </section>
        {% endfor %}
      </div>
      <aside class="sidebar">
        {% for block in side_blocks %}
        <div style="margin-bottom:16px;">
          <h3>{{ block.title }}</h3>
          <div class="mini-list">
            {% for item in block["items"] %}
            <div class="mini-row">{{ item|safe }}</div>
            {% endfor %}
          </div>
        </div>
        {% endfor %}
      </aside>
    </div>
  </div>
</body>
</html>
"""


